#!/usr/bin/env python3
"""Strict CSV parsing, formatting, JSON conversion, and command-line support."""

import csv
import io
import json
import sys
from typing import Iterable

_HEADER = ["name", "note"]
_KEYS = {"name", "note"}


def _validate_quoting(text: str) -> None:
    """Reject quotes that do not follow CSV's quoted-field grammar."""
    in_quotes = False
    at_field_start = True
    just_closed = False
    index = 0

    while index < len(text):
        char = text[index]

        if in_quotes:
            if char == '"':
                if index + 1 < len(text) and text[index + 1] == '"':
                    index += 2
                    continue
                in_quotes = False
                just_closed = True
            index += 1
            continue

        if just_closed:
            if char == ",":
                at_field_start = True
                just_closed = False
            elif char == "\n":
                at_field_start = True
                just_closed = False
            elif char == "\r":
                at_field_start = True
                just_closed = False
                if index + 1 < len(text) and text[index + 1] == "\n":
                    index += 1
            else:
                raise ValueError(
                    "malformed CSV quoting: unexpected character after closing quote"
                )
            index += 1
            continue

        if char == '"':
            if not at_field_start:
                raise ValueError(
                    "malformed CSV quoting: quote inside an unquoted field"
                )
            in_quotes = True
            at_field_start = False
        elif char == ",":
            at_field_start = True
        elif char == "\n":
            at_field_start = True
        elif char == "\r":
            at_field_start = True
            if index + 1 < len(text) and text[index + 1] == "\n":
                index += 1
        else:
            at_field_start = False
        index += 1

    if in_quotes:
        raise ValueError("malformed CSV quoting: unterminated quoted field")


def parse_records(text: str) -> list[dict[str, str]]:
    """Parse CSV with the exact header ``name,note`` into record dictionaries."""
    if not isinstance(text, str):
        raise ValueError("CSV input must be a string")

    _validate_quoting(text)
    try:
        rows = list(csv.reader(io.StringIO(text, newline=""), strict=True))
    except csv.Error as exc:
        raise ValueError(f"malformed CSV: {exc}") from None

    if not rows:
        raise ValueError("missing CSV header; expected name,note")
    if rows[0] != _HEADER:
        raise ValueError("invalid CSV header; expected exactly name,note")

    records: list[dict[str, str]] = []
    for row_number, row in enumerate(rows[1:], start=2):
        if len(row) != 2:
            raise ValueError(
                f"row {row_number} has {len(row)} columns; expected 2"
            )
        records.append({"name": row[0], "note": row[1]})
    return records


def format_records(records: Iterable[dict[str, str]]) -> str:
    """Serialize validated records as CSV using LF line terminators."""
    try:
        iterator = iter(records)
    except TypeError:
        raise ValueError("records must be an iterable of dictionaries") from None

    validated: list[tuple[str, str]] = []
    for index, record in enumerate(iterator, start=1):
        if not isinstance(record, dict):
            raise ValueError(f"record {index} must be a dictionary")
        if set(record) != _KEYS:
            raise ValueError(
                f"record {index} must contain exactly the keys name and note"
            )
        name = record["name"]
        note = record["note"]
        if not isinstance(name, str) or not isinstance(note, str):
            raise ValueError(f"record {index} values must be strings")
        validated.append((name, note))

    output = io.StringIO(newline="")
    writer = csv.writer(output, lineterminator="\n")
    writer.writerow(_HEADER)
    writer.writerows(validated)
    return output.getvalue()


def to_json(text: str) -> str:
    """Convert valid CSV text to JSON without ASCII-escaping Unicode values."""
    return json.dumps(parse_records(text), ensure_ascii=False)


def main() -> int:
    try:
        result = to_json(sys.stdin.read())
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2

    print(result)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
